// 기존 일정 관리 데이터를 Work MVP 형식으로 변환하는 어댑터
import type { ScheduleEvent, TodoItem } from '../types';
import type { ProjectTask, ProjectTodo } from '../types/work';

// 읽기 전용 마커 (id prefix)
export const SCHEDULE_EVENT_PREFIX = 'schedule_';
export const TODO_ITEM_PREFIX = 'todoitem_';

// ScheduleEvent를 ProjectTask 형식으로 변환 (읽기 전용)
export function scheduleEventToTaskView(event: ScheduleEvent): ProjectTask & { isReadOnly: true; sourceType: 'schedule' } {
  // 시작/종료 시간을 ISO datetime으로 변환
  const startDateTime = event.start ? `${event.date}T${event.start}:00` : null;
  const endDateTime = event.end 
    ? `${event.endDate || event.date}T${event.end}:00` 
    : null;

  return {
    id: `${SCHEDULE_EVENT_PREFIX}${event.id}`,
    projectId: null,
    title: event.title,
    start_at: startDateTime,
    end_at: endDateTime,
    due_at: null,
    is_all_day: false,
    status: event.status === 'done' ? 'DONE' : 'ACTIVE',
    completed_at: event.status === 'done' ? event.updatedAt : null,
    priority_order_index: 999999, // 맨 뒤에 표시
    unscheduled_order_index: 999999,
    created_at: event.createdAt,
    updated_at: event.updatedAt,
    // 읽기 전용 마커
    isReadOnly: true,
    sourceType: 'schedule',
  };
}

// TodoItem을 ProjectTodo 형식으로 변환 (읽기 전용)
export function todoItemToTodoView(todo: TodoItem): ProjectTodo & { isReadOnly: true; sourceType: 'todo' } {
  // 날짜를 ISO datetime으로 변환 (종일)
  const dateTime = todo.date ? `${todo.date}T00:00:00` : null;

  return {
    id: `${TODO_ITEM_PREFIX}${todo.id}`,
    taskId: null,
    content: todo.title,
    start_at: dateTime,
    end_at: null,
    due_at: dateTime, // 날짜를 마감일로 처리
    is_all_day: true,
    is_done: todo.status === 'done',
    completed_at: todo.status === 'done' ? todo.updatedAt : null,
    priority_order_index: 999999,
    unscheduled_order_index: 999999,
    created_at: todo.createdAt,
    updated_at: todo.updatedAt,
    // 읽기 전용 마커
    isReadOnly: true,
    sourceType: 'todo',
  };
}

// 여러 ScheduleEvent를 변환
export function scheduleEventsToTaskViews(events: ScheduleEvent[]): (ProjectTask & { isReadOnly: true; sourceType: 'schedule' })[] {
  return events.map(scheduleEventToTaskView);
}

// 여러 TodoItem을 변환
export function todoItemsToTodoViews(todos: TodoItem[]): (ProjectTodo & { isReadOnly: true; sourceType: 'todo' })[] {
  return todos.map(todoItemToTodoView);
}

// 읽기 전용 여부 확인
export function isReadOnlyItem(id: string): boolean {
  return id.startsWith(SCHEDULE_EVENT_PREFIX) || id.startsWith(TODO_ITEM_PREFIX);
}

// 원본 ID 추출
export function getOriginalId(id: string): string {
  if (id.startsWith(SCHEDULE_EVENT_PREFIX)) {
    return id.slice(SCHEDULE_EVENT_PREFIX.length);
  }
  if (id.startsWith(TODO_ITEM_PREFIX)) {
    return id.slice(TODO_ITEM_PREFIX.length);
  }
  return id;
}
